package app.rafiq.personal;
import android.app.Activity;
import android.os.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import com.google.android.gms.wearable.*;
import org.json.*;
import java.util.UUID;

public class WatchActivity extends Activity implements DataClient.OnDataChangedListener {
 JSONObject plan=new JSONObject();int selected=0,tab=0;LinearLayout layout;TextView status,timer,pulse,pulseState;EditText weight,reps;CountDownTimer countdown;WatchSensors sensors;long lastSend=0;
 final int GREEN=Color.rgb(255,149,74),BLUE=Color.rgb(255,189,142),PURPLE=Color.rgb(224,224,224),BG=Color.rgb(11,11,11),MUTED=Color.rgb(170,170,170);
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 @Override public void onCreate(Bundle state){super.onCreate(state);try{plan=new JSONObject(getPreferences(0).getString("plan","{}"));}catch(Exception ignored){}sensors=new WatchSensors(this,new WatchSensors.Callback(){public void state(String text){if(pulseState!=null)pulseState.setText(text);}public void reading(float bpm,int accuracy){if(pulse!=null)pulse.setText(String.valueOf(Math.round(bpm)));if(pulseState!=null)pulseState.setText("نبضة/د · من حساس الساعة الآن");long now=System.currentTimeMillis();if(now-lastSend>=10000){lastSend=now;try{send(new JSONObject().put("type","heart").put("bpm",bpm).put("accuracy",accuracy),false);}catch(Exception ignored){}}}});render();}
 @Override public void onResume(){super.onResume();resendFood();Wearable.getDataClient(this).addListener(this);Wearable.getDataClient(this).getDataItems().addOnSuccessListener(items->{try{for(DataItem item:items)read(item);}finally{items.release();}});}
 @Override public void onPause(){sensors.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);Wearable.getDataClient(this).removeListener(this);super.onPause();}
 void read(DataItem item){if(item.getUri().getPath().startsWith("/rafiq/ack/")){receiveAck(item);return;}if(!"/rafiq/plan".equals(item.getUri().getPath()))return;try{JSONObject next=new JSONObject(DataMapItem.fromDataItem(item).getDataMap().getString("json"));boolean changed=!next.optString("sessionId").equals(plan.optString("sessionId"));plan=next;getPreferences(0).edit().putString("plan",plan.toString()).apply();if(changed)selected=0;runOnUiThread(()->{if(tab==0||changed)render();});}catch(Exception ignored){}}
 @Override public void onDataChanged(DataEventBuffer events){for(DataEvent e:events)if(e.getType()==DataEvent.TYPE_CHANGED)read(e.getDataItem());}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setFontFeatureSettings("tnum");t.setPadding(0,dp(3),0,dp(3));layout.addView(t);return t;}
 Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(GREEN);b.setBackground(bg(Color.rgb(41,30,22),24));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.setMargins(0,dp(7),0,dp(3));layout.addView(b,lp);return b;}
 EditText number(String label,double value){text(label,10,MUTED);EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);e.setText(String.valueOf(value));e.setTextColor(Color.WHITE);e.setTextSize(23);e.setGravity(Gravity.CENTER);e.setBackground(bg(Color.rgb(30,30,30),14));layout.addView(e,new LinearLayout.LayoutParams(-1,dp(48)));return e;}
 void render(){pulse=null;pulseState=null;ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(BG);layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(dp(20),dp(18),dp(20),dp(32));scroll.addView(layout);setContentView(scroll);text("رَفِيق / PERFORMANCE",9,GREEN);
 LinearLayout tabs=new LinearLayout(this);for(int i=0;i<4;i++){final int destination=i;Button b=new Button(this);b.setText(new String[]{"يومي","تمرين","أكل","نبض"}[i]);b.setTextSize(9);b.setAllCaps(false);b.setTextColor(i==tab?BG:MUTED);b.setBackground(bg(i==tab?GREEN:Color.rgb(29,29,29),20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(28),1);lp.setMargins(dp(2),dp(5),dp(2),dp(3));tabs.addView(b,lp);b.setOnClickListener(v->{if(destination!=tab){sensors.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}tab=destination;render();});}layout.addView(tabs);
 if(tab==0)home();else if(tab==1)workout();else if(tab==2)food();else heart();
 status=text("المزامنة مع موبايلك عند الاتصال",9,MUTED);button("فحص تحديث التطبيق",this::checkUpdate);try{text("v"+getPackageManager().getPackageInfo(getPackageName(),0).versionName,9,MUTED);}catch(Exception ignored){}
 }
 void home(){float readiness=(float)plan.optDouble("readiness",-1),sleep=(float)plan.optDouble("sleepPercent",0),food=plan.optInt("goal",0)>0?plan.optInt("kcal",0)*100f/plan.optInt("goal",1):0;layout.addView(new VitalRings(this,readiness,sleep,food),new LinearLayout.LayoutParams(-1,dp(108)));text(readiness<0?"نبني خطك الأساسي":"جاهزية تقديرية من رفيق",10,GREEN);text("النوم "+(plan.has("sleepHours")?plan.optString("sleepHours")+" س":"—")+"  ·  HRV "+(plan.has("hrv")?plan.optString("hrv"):"—"),11,PURPLE);text(plan.optString("name","افتح رفيق على الموبايل"),17,Color.WHITE);button("افتح جلسة التمرين",()->{tab=1;render();});button("سجّل أكلك",()->{tab=2;render();});text("الغذاء "+plan.optInt("kcal",0)+" / "+plan.optInt("goal",0)+" سعرة",11,MUTED);text("الماي "+plan.optInt("water",0)+" مل",12,BLUE);button("+ 250 مل ماي",()->{try{send(new JSONObject().put("type","water").put("ml",250),true);}catch(Exception ignored){}});text("الدوائر: جاهزية · نوم · غذاء",9,MUTED);}
 void workout(){JSONArray exercises=plan.optJSONArray("exercises");if(exercises==null||exercises.length()==0){text("افتح تمرينك بالموبايل حتى توصل الخطة",13,MUTED);return;}selected=Math.min(selected,exercises.length()-1);JSONObject ex=exercises.optJSONObject(selected);text(plan.optString("name")+"  /  "+(selected+1)+" من "+exercises.length(),10,GREEN);text(ex.optString("name"),19,Color.WHITE);text(ex.optString("sets")+" × "+ex.optString("reps")+" · "+ex.optString("unit"),11,MUTED);weight=number("الوزن",storedNumber("weight-"+ex.optString("id"),ex.optDouble("weight",0)));reps=number("التكرارات",storedNumber("reps-"+ex.optString("id"),10));button("✓ سجّل الجولة",()->{try{double w=Double.parseDouble(weight.getText().toString()),r=Double.parseDouble(reps.getText().toString());if(!Double.isFinite(w)||w<0||w>2000||r<1||r>300||r!=Math.floor(r)){status.setText("راجع الأوزان والتكرارات");return;}JSONObject event=new JSONObject().put("type","set").put("sessionId",plan.getString("sessionId")).put("exerciseId",ex.getString("id")).put("name",ex.getString("name")).put("unit",ex.getString("unit")).put("basis",ex.getString("basis")).put("weight",w).put("reps",r);send(event,true);getPreferences(0).edit().putString("weight-"+ex.optString("id"),String.valueOf(w)).putString("reps-"+ex.optString("id"),String.valueOf(r)).apply();startRest(ex.optInt("rest",90));}catch(Exception e){status.setText("أدخل أرقاماً صحيحة");}});timer=text("مؤقت الراحة",25,PURPLE);button("ابدأ راحة",()->startRest(ex.optInt("rest",90)));button("التمرين التالي ←",()->{selected=(selected+1)%exercises.length();render();});button("→ التمرين السابق",()->{selected=(selected+exercises.length()-1)%exercises.length();render();});}
 double storedNumber(String key,double fallback){try{return Double.parseDouble(getPreferences(0).getString(key,String.valueOf(fallback)));}catch(Exception e){return fallback;}}
 void heart(){text("نبضك، هسه.",21,Color.WHITE);pulse=text("—",58,Color.rgb(251,142,133));pulse.setTypeface(Typeface.create("sans-serif-light",0));pulseState=text("قراءة مباشرة باختيارك",11,MUTED);button("بدء قياس النبض",()->{getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);sensors.start();});button("إيقاف القياس",()->{sensors.stop();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);pulse.setText("—");pulseState.setText("توقف القياس");});text("القياس أثناء فتح الشاشة فقط. تنحفظ قراءة كل 10 ثوانٍ للمزامنة. لا نقيس HRV من معدل النبض.",10,MUTED);}
 @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] results){super.onRequestPermissionsResult(requestCode,permissions,results);if(requestCode==41){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)sensors.start();else if(pulseState!=null)pulseState.setText("صلاحية النبض مطلوبة لبدء القياس");}}

 void receiveAck(DataItem item){try{JSONArray ids=new JSONArray(DataMapItem.fromDataItem(item).getDataMap().getString("ids","[]"));java.util.HashSet<String> saved=new java.util.HashSet<>();for(int i=0;i<ids.length();i++)saved.add(ids.getString(i));JSONArray queue=new JSONArray(getPreferences(0).getString("foodQueue","[]")),next=new JSONArray();for(int i=0;i<queue.length();i++){JSONObject e=queue.getJSONObject(i);if(!saved.contains(e.optString("id")))next.put(e);}if(getPreferences(0).edit().putString("foodQueue",next.toString()).commit()){Wearable.getDataClient(this).deleteDataItems(item.getUri());if(next.length()<queue.length())runOnUiThread(()->{if(status!=null)status.setText("الموبايل استلم أكلك وحفظه ✓");});}}catch(Exception ignored){}}
 void food(){
  text("أكلك، من معصمك.",17,Color.WHITE);
  text("القيم المعروفة تنحفظ بعد مراجعتك. الوصف بدون قيم يروح للموبايل حتى تكمله.",10,MUTED);
  button("+ وجبة جديدة / وصف أكلة",()->foodEditor(null));
  JSONArray templates=plan.optJSONArray("foodTemplates"),recent=plan.optJSONArray("recentFoods");
  text("وجباتك المعتادة",12,GREEN);
  if(templates==null||templates.length()==0)text("ثبّت وجباتك من الموبايل وافتحه للمزامنة",10,MUTED);
  if(templates!=null)for(int i=0;i<templates.length();i++){final JSONObject meal=templates.optJSONObject(i);if(meal!=null)button(meal.optString("name"),()->portionEditor(meal));}
  text("من سجلك الأخير",12,GREEN);
  if(recent!=null)for(int i=0;i<recent.length();i++){final JSONObject meal=recent.optJSONObject(i);if(meal!=null)button(meal.optString("name"),()->portionEditor(meal));}
  button("وجبات تنتظر وصول الموبايل",this::showFoodQueue);
 }
 EditText foodField(LinearLayout parent,String label,String value,boolean numeric){
  TextView title=new TextView(this);title.setText(label);title.setTextColor(MUTED);title.setTextSize(11);title.setPadding(0,dp(9),0,dp(4));parent.addView(title);
  EditText input=new EditText(this);input.setText(value);input.setTextSize(14);input.setTextColor(Color.WHITE);input.setInputType(numeric?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);input.setSingleLine(!numeric);input.setBackground(bg(Color.rgb(30,30,30),10));input.setPadding(dp(10),dp(5),dp(10),dp(5));parent.addView(input,new LinearLayout.LayoutParams(-1,dp(44)));return input;
 }
 LinearLayout foodForm(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),dp(8),dp(12),dp(24));return form;}
 ScrollView foodScroll(LinearLayout form){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(BG);scroll.addView(form);return scroll;}
 Button foodAction(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextColor(GREEN);b.setTextSize(12);b.setAllCaps(false);b.setBackground(bg(Color.rgb(41,30,22),22));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.setMargins(0,dp(9),0,dp(5));parent.addView(b,lp);if(action!=null)b.setOnClickListener(v->action.run());return b;}
 void portionEditor(JSONObject base){LinearLayout form=foodForm();EditText portions=foodField(form,"عدد الحصص من نفس الكمية والتحضير","1",true);TextView hint=new TextView(this);hint.setText("نصف حصة = 0.5. إذا تغيّر التحضير عدّل القيم قبل الحفظ.");hint.setTextColor(MUTED);hint.setTextSize(11);form.addView(hint);android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle(base.optString("name")).setView(foodScroll(form)).create();foodAction(form,"راجع الوجبة",()->{try{double factor=Double.parseDouble(portions.getText().toString());if(!Double.isFinite(factor)||factor<=0||factor>20)throw new Exception();JSONObject scaled=new JSONObject(base.toString());for(String field:new String[]{"grams","kcal","protein","carbs","fat"})scaled.put(field,Math.round(base.optDouble(field)*factor*10)/10.0);dialog.dismiss();foodEditor(scaled);}catch(Exception e){portions.setError("أدخل حصصاً من أكثر من صفر إلى 20");}});foodAction(form,"رجوع",dialog::dismiss);dialog.show();}
 void foodEditor(JSONObject base){
  LinearLayout form=foodForm();EditText name=foodField(form,"شنو أكلت؟",base==null?"":base.optString("name"),false),grams=foodField(form,"الكمية بالغرام (اختياري للوصف)",base==null?"":base.optString("grams"),true),preparation=foodField(form,"التحضير / نيء أو مطبوخ",base==null?"":base.optString("preparation"),false);
  CheckBox known=new CheckBox(this);known.setText("القيم الغذائية معروفة عندي");known.setTextSize(11);known.setTextColor(Color.WHITE);known.setChecked(base!=null);form.addView(known);
  LinearLayout macros=new LinearLayout(this);macros.setOrientation(LinearLayout.VERTICAL);form.addView(macros);EditText kcal=foodField(macros,"السعرات",base==null?"":base.optString("kcal"),true),protein=foodField(macros,"البروتين غ",base==null?"":base.optString("protein"),true),carbs=foodField(macros,"الكارب غ",base==null?"":base.optString("carbs"),true),fat=foodField(macros,"الدهون غ",base==null?"":base.optString("fat"),true);macros.setVisibility(known.isChecked()?View.VISIBLE:View.GONE);known.setOnCheckedChangeListener((b,checked)->macros.setVisibility(checked?View.VISIBLE:View.GONE));
  TextView info=new TextView(this);info.setText("الحفظ مرة واحدة بعد مراجعتك. إذا القيم مو معروفة، ينحفظ وصف للمراجعة وما ينضاف للسعرات.");info.setTextColor(MUTED);info.setTextSize(10);form.addView(info);
  android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle("راجع أكلك").setView(foodScroll(form)).create();
  Button save=foodAction(form,"تأكيد الحفظ",null);foodAction(form,"إلغاء",dialog::dismiss);
  save.setOnClickListener(x->{try{
   String title=name.getText().toString().trim(),prep=preparation.getText().toString().trim();if(title.isEmpty()||title.length()>300){name.setError("اكتب وصفاً من 1 إلى 300 حرف");return;}if(prep.length()>1000){preparation.setError("الوصف طويل");return;}
   Double amount=grams.getText().toString().trim().isEmpty()?null:foodNumber(grams,20000);
   JSONObject event=new JSONObject().put("type",known.isChecked()?"meal":"foodDraft").put("name",title).put("grams",amount==null?JSONObject.NULL:amount).put("preparation",prep).put("original",title+(amount==null?"":" · "+amount+" غ")+" · "+prep);
   if(known.isChecked()){if(amount==null){grams.setError("حدد الكمية قبل تسجيل وجبة كاملة");return;}event.put("kcal",foodNumber(kcal,20000)).put("protein",foodNumber(protein,2000)).put("carbs",foodNumber(carbs,2000)).put("fat",foodNumber(fat,2000));}
   save.setEnabled(false);save.setText("نحفظ…");queueFood(event,()->{dialog.dismiss();if(status!=null)status.setText(known.isChecked()?"الوجبة محفوظة على الساعة ✓":"الوصف محفوظ للمراجعة بالموبايل ✓");vibrate();},()->{save.setEnabled(true);save.setText("تأكيد الحفظ");name.setError("تعذر الحفظ المحلي؛ جرّب مرة ثانية");});
  }catch(Exception e){if(status!=null)status.setText("راجع الأرقام والحقول");}});dialog.show();
 }
 double foodNumber(EditText input,double max)throws Exception{try{double value=Double.parseDouble(input.getText().toString());if(!Double.isFinite(value)||value<0||value>max)throw new Exception();return value;}catch(Exception e){input.setError("رقم من 0 إلى "+Math.round(max));throw e;}}
 void queueFood(JSONObject event,Runnable success,Runnable failure){try{String id=UUID.randomUUID().toString();event.put("id",id).put("time",java.time.Instant.now().toString());JSONArray queue=new JSONArray(getPreferences(0).getString("foodQueue","[]"));queue.put(event);if(!getPreferences(0).edit().putString("foodQueue",queue.toString()).commit()){failure.run();return;}publishFood(event);success.run();}catch(Exception e){failure.run();}}
 void publishFood(JSONObject event){try{PutDataMapRequest map=PutDataMapRequest.create("/rafiq/event/"+event.getString("id"));map.getDataMap().putString("json",event.toString());Wearable.getDataClient(this).putDataItem(map.asPutDataRequest().setUrgent());}catch(Exception ignored){}}
 void resendFood(){try{JSONArray queue=new JSONArray(getPreferences(0).getString("foodQueue","[]"));for(int i=0;i<queue.length();i++)publishFood(queue.getJSONObject(i));}catch(Exception ignored){}}
 void showFoodQueue(){try{JSONArray queue=new JSONArray(getPreferences(0).getString("foodQueue","[]"));StringBuilder message=new StringBuilder();for(int i=0;i<queue.length();i++)message.append("• ").append(queue.getJSONObject(i).optString("name")).append("\n");new android.app.AlertDialog.Builder(this).setTitle(queue.length()+" وجبات محفوظة محلياً").setMessage(queue.length()==0?"ماكو وجبات تنتظر. افتح رفيق بالموبايل حتى تتأكد من السجل.":message.toString()+"\nافتح رفيق بالموبايل للمزامنة. هذه قائمة انتظار وليست مجموع الأكل.").setPositiveButton("إعادة محاولة المزامنة",(d,w)->resendFood()).setNegativeButton("إغلاق",null).show();}catch(Exception ignored){}}
 void checkUpdate(){status.setText("نفحص التحديث…");new Thread(()->{try{String installed=getPackageManager().getPackageInfo(getPackageName(),0).versionName;JSONObject result=UpdateCheck.check(installed,"Rafiq-watch.apk");runOnUiThread(()->{if(result.optBoolean("available"))new android.app.AlertDialog.Builder(this).setTitle("تحديث "+result.optString("version")).setMessage("نزّل Rafiq-watch.apk من صفحة إصدارات رفيق وثبّته عبر ADB اللاسلكي. لا تحذف التطبيق الحالي.").setPositiveButton("تمام",null).show();else status.setText("عندك أحدث إصدار ✓");});}catch(Exception e){runOnUiThread(()->status.setText("تعذر الفحص؛ تأكد من الإنترنت"));}}).start();}
 void send(JSONObject event,boolean feedback)throws JSONException{String id=UUID.randomUUID().toString();event.put("id",id).put("time",java.time.Instant.now().toString());PutDataMapRequest map=PutDataMapRequest.create("/rafiq/event/"+id);map.getDataMap().putString("json",event.toString());Wearable.getDataClient(this).putDataItem(map.asPutDataRequest().setUrgent()).addOnSuccessListener(x->{if(feedback){status.setText("انحفظ للمزامنة ✓");vibrate();}}).addOnFailureListener(e->{if(status!=null)status.setText("تعذرت المزامنة؛ جرّب مرة ثانية");});}
 void startRest(int seconds){if(countdown!=null)countdown.cancel();countdown=new CountDownTimer(Math.max(1,seconds)*1000L,1000){public void onTick(long n){if(timer!=null)timer.setText((n/60000)+":"+String.format(java.util.Locale.US,"%02d",(n/1000)%60));}public void onFinish(){if(timer!=null)timer.setText("جاهز للجولة؟");vibrate();}}.start();}
 void vibrate(){android.os.Vibrator v=(android.os.Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null)v.vibrate(VibrationEffect.createOneShot(100,VibrationEffect.DEFAULT_AMPLITUDE));}
 @Override public void onDestroy(){sensors.stop();if(countdown!=null)countdown.cancel();super.onDestroy();}
}
